draw:
var g = 9.8, vt = p.vt;
var tmax = 4 * vt / g;
var pad = 38;
var gw = W - pad - 16, gh = H - pad - 26;
var x0 = pad, y0 = 20;
var vmax = vt * 1.45;
function X(s) { return x0 + gw * s / tmax; }
function V(v) { return y0 + gh - gh * v / vmax; }

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(x0, y0); ctx.lineTo(x0, y0 + gh); ctx.lineTo(x0 + gw, y0 + gh);
ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("v (m/s)", x0 - 30, y0 + 4);
ctx.fillText("t (s)", x0 + gw - 18, y0 + gh + 16);
ctx.fillText("0", x0 - 12, y0 + gh + 4);
ctx.fillText(tmax.toFixed(1), x0 + gw - 10, y0 + gh + 16);

/* terminal speed line */
ctx.setLineDash([4, 5]); ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(x0, V(vt)); ctx.lineTo(x0 + gw, V(vt)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("terminal speed " + vt.toFixed(1) + " m/s", x0 + 8, V(vt) - 6);

/* no-drag line v = gt */
ctx.strokeStyle = C.figure; ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(X(0), V(0));
var send = vmax / g < tmax ? vmax / g : tmax;
ctx.lineTo(X(send), V(g * send));
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("no drag: v = gt", X(send) + 4, V(g * send) + 14);

/* with drag */
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 160; i++) {
  var s = tmax * i / 160;
  var v = vt * (1 - Math.exp(-g * s / vt));
  i === 0 ? ctx.moveTo(X(s), V(v)) : ctx.lineTo(X(s), V(v));
}
ctx.stroke();

/* time constant marker */
var tau = vt / g;
ctx.setLineDash([2, 3]); ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(X(tau), y0 + gh); ctx.lineTo(X(tau), V(0.632 * vt)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("t = vt/g", X(tau) - 16, y0 + gh + 16);

/* sweeping cursor */
var now = t % tmax;
var vnow = vt * (1 - Math.exp(-g * now / vt));
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(now), V(vnow), 5, 0, Math.PI * 2); ctx.fill();
ctx.strokeStyle = C.figure; ctx.lineWidth = 1;
ctx.setLineDash([2, 3]);
ctx.beginPath(); ctx.moveTo(X(now), V(vnow)); ctx.lineTo(x0, V(vnow)); ctx.stroke();
ctx.setLineDash([]);

out.note = "t = " + now.toFixed(2) + " s: with drag v = " + vnow.toFixed(2) +
  " m/s (" + (100 * vnow / vt).toFixed(0) + "% of terminal), without drag v = " +
  (g * now).toFixed(1) + " m/s";
